import{_ as e,o as t,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"产品范围与架构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"architecture/lab-word.md","filePath":"architecture/lab-word.md"}'),n={name:"architecture/lab-word.md"};function o(l,a,s,b,i,c){return t(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="产品范围与架构" tabindex="-1">产品范围与架构 <a class="header-anchor" href="#产品范围与架构" aria-label="Permalink to &quot;产品范围与架构&quot;">​</a></h1><p>Lab Word 的产品目标是实验室数字孪生。当前阶段聚焦设备模型的三维呈现，空间摆放与来源明确的真实状态在后续阶段建立。术语见 <a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>。</p><h2 id="模型与设备的关系" tabindex="-1">模型与设备的关系 <a class="header-anchor" href="#模型与设备的关系" aria-label="Permalink to &quot;模型与设备的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab Word</span></span>
<span class="line"><span>  └─ Lab Viewer</span></span>
<span class="line"><span>       └─ Lab Layout</span></span>
<span class="line"><span>            └─ Equipment Instance ──使用──&gt; Equipment Model</span></span></code></pre></div><p>Equipment Model 是可复用三维资产；Equipment Instance 是具有独立身份和位置的一台设备。同一个模型可以表达多台设备，不能用模型文件名替代设备身份。当前单模型预览尚不建立持久布局。</p><h2 id="已有实现与目标接入" tabindex="-1">已有实现与目标接入 <a class="header-anchor" href="#已有实现与目标接入" aria-label="Permalink to &quot;已有实现与目标接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>当前状态</th><th>后续责任</th></tr></thead><tbody><tr><td>通用应用壳、身份、成员、知识库</td><td>现有应用代码</td><td>为 Lab 提供宿主与共享能力</td></tr><tr><td>Lab Viewer v1</td><td>已接受的隔离预览</td><td>将导入、相机、选择与指标接入正式应用</td></tr><tr><td>Lab 导航与登录后默认入口</td><td>已确定，正式集成验收待完成</td><td>显式组装 Lab 业务贡献</td></tr><tr><td>多设备布局、现实设备数据</td><td>后续范围</td><td>定义实例持久化与状态来源</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>选择复用现有 SaaS 底座：Lab 拥有设备与布局业务，Core 保持身份、成员等公共职责。正式 Lab 的集成与验收仍待完成；接入点见<a href="./project-structure">项目结构</a>。</p><h2 id="当前呈现层边界" tabindex="-1">当前呈现层边界 <a class="header-anchor" href="#当前呈现层边界" aria-label="Permalink to &quot;当前呈现层边界&quot;">​</a></h2><p>首版查看一份资源内嵌的 GLB，支持文件选择与拖入、自动居中与取景、旋转/缩放/平移、点击选择、回到示例和渲染指标。导入文件停留在浏览器会话，不增加服务器上传或云资产库。</p><p>保持模型原始尺度。缺失外部资源、无几何或解码失败须明确反馈，保留前一个可用模型。替换与离开页面需释放独占 GPU 资源，快速切换不能让旧结果覆盖新模型。这些是目标验收合同，生产实现仍待完成。</p><p>未来 Three.js 相关代码随 Lab 页面按需加载，正式包体预算另行实测。当前预览的构建与软件渲染指标不能证明生产性能。</p><h2 id="继续开发" tabindex="-1">继续开发 <a class="header-anchor" href="#继续开发" aria-label="Permalink to &quot;继续开发&quot;">​</a></h2><p>先按<a href="./../guides/lab-viewer">预览指南</a>观察设备与导入，再将已验收体验转为公开行为测试。具体范围和资产记录见<a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/plans/lab-viewer-m0.md" target="_blank" rel="noreferrer">呈现层计划</a>，职责规则见<a href="./module-boundaries">模块边界</a>。</p><hr><p>源码版本：<code>55a27be3bc71</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/55a27be3bc717ebedda94f81a2c6d9e6d4dd7012/docs/architecture/lab-word.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,16)])])}const u=e(n,[["render",o]]);export{h as __pageData,u as default};
